//! Bengali inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki Bengali dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Case {
    Nominative,
    Objective,
    Genitive,
    Locative,
}

impl Case {
    pub const ALL: [Self; 4] = [Self::Nominative, Self::Objective, Self::Genitive, Self::Locative];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Person {
    First,
    SecondIntimate,
    SecondFamiliar,
    Third,
    Polite,
}

impl Person {
    pub const ALL: [Self; 5] = [Self::First, Self::SecondIntimate, Self::SecondFamiliar, Self::Third, Self::Polite];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Tense {
    Present,
    PresentContinuous,
    PresentPerfect,
    Past,
    PastContinuous,
    PastPerfect,
    PastHabitual,
    Future,
}

impl Tense {
    pub const ALL: [Self; 8] = [Self::Present, Self::PresentContinuous, Self::PresentPerfect, Self::Past, Self::PastContinuous, Self::PastPerfect, Self::PastHabitual, Self::Future];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Participle {
    Perfect,
    Conditional,
}

impl Participle {
    pub const ALL: [Self; 2] = [Self::Perfect, Self::Conditional];
}

