    /// A noun form (indefinite).
    pub fn noun_indefinite_scored(&self, word: &str, case: Case) -> Scored<String> {
        let cell: Option<u32> = match (case,) {
            (Case::Nominative,) => Some(0),
            (Case::Objective,) => Some(1),
            (Case::Genitive,) => Some(2),
            (Case::Locative,) => Some(3),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

